from __future__ import annotations

import asyncio
from types import SimpleNamespace
from typing import TYPE_CHECKING

from ds.util.logging import logger
from pydantic_ai.messages import ModelRequest, ModelResponse, TextPart, UserPromptPart
from pydantic_ai.models.test import TestModel
from starlette.testclient import TestClient
from ui import agents, inline_terminal, terminal
from ui.api import api

if TYPE_CHECKING:
    import pytest


def ask(body: dict[str, str], **output: str) -> dict[str, str]:
    with inline_terminal.command_agent.override(model=TestModel(custom_output_args=output)):
        return asyncio.run(inline_terminal.ask(body))


def test_the_model_gets_the_screen_and_the_instruction() -> None:
    text = inline_terminal.prompt("$ ls\nREADME.md", "count the files")
    assert text == "Terminal screen:\n```\n$ ls\nREADME.md\n```\n\nInstruction: count the files"
    assert "(nothing on screen)" in inline_terminal.prompt("  \n", "x")


def test_only_the_end_of_a_huge_screen_is_sent() -> None:
    text = inline_terminal.prompt("~" * (inline_terminal.MAX_SCREEN_CHARS + 50) + "END", "x")
    assert text.count("~") == inline_terminal.MAX_SCREEN_CHARS - 3
    assert "END" in text


def test_a_one_line_command_comes_back_with_what_it_used() -> None:
    answer = ask({"instruction": "rerun what failed", "screen": "$"}, command="$ uv run pytest --lf -x\n")
    assert answer["command"] == "uv run pytest --lf -x"
    assert answer["usage"].endswith("1 request")


def test_a_question_gets_a_note_and_no_command() -> None:
    answer = ask({"instruction": "why did that fail?"}, command="", note="`ui` is not on the path.")
    assert "command" not in answer
    assert answer["note"] == "`ui` is not on the path."


def test_several_lines_are_never_typed() -> None:
    answer = ask({"instruction": "clean up"}, command="cd /tmp\nrm -rf x")
    assert "command" not in answer
    assert "several lines" in answer["error"]


def test_it_needs_an_instruction() -> None:
    assert "error" in asyncio.run(inline_terminal.ask({"instruction": "  ", "screen": "$"}))


def test_it_reads_the_chat_and_adds_nothing_to_it(monkeypatch: pytest.MonkeyPatch) -> None:
    history = [ModelRequest(parts=[UserPromptPart("who is ranked first?")]), ModelResponse(parts=[TextPart("Sonix")])]
    session = SimpleNamespace(ai_history=list(history), ai_cost=0.0)
    monkeypatch.setattr(inline_terminal, "find_session", lambda _token: session)
    model = TestModel(custom_output_args={"command": "ls"})
    with inline_terminal.command_agent.override(model=model):
        asyncio.run(inline_terminal.ask({"instruction": "list", "token": "t"}))
    assert session.ai_history == history


def test_the_call_is_logged_as_an_inline_one() -> None:
    seen: list[dict[str, object]] = []
    sink = logger.add(lambda message: seen.append(message.record["extra"]), level="INFO")
    try:
        ask({"instruction": "list files", "screen": "$"}, command="ls")
    finally:
        logger.remove(sink)
    record = next(extra for extra in seen if extra.get("source") == "inline-terminal")
    assert record["kind"] == "agent"
    assert record["origin"] == "inline terminal"


def test_the_agent_is_listed_with_the_other_inline_chats() -> None:
    assert "inline-terminal" in [info.name for info in agents.AGENTS]


def test_only_this_machines_pages_may_ask() -> None:
    client = TestClient(api, client=("127.0.0.1", 50000))
    refused = client.post("/inline_terminal", json={"instruction": "x"}, headers={"origin": "https://example.com"})
    assert refused.status_code == 403
    allowed = client.post("/inline_terminal", json={"instruction": " "}, headers={"origin": "http://localhost:8000"})
    assert allowed.json() == {"error": "Type what you want first."}


def test_the_page_has_the_box_and_calls_the_route() -> None:
    for piece in ("inlineBox(", '"KeyI"', 'fetch("/inline_terminal"', "term.paste(answer.command)"):
        assert piece in terminal.PAGE


def test_the_terminal_gets_the_same_box_as_a_cell() -> None:
    served = TestClient(api).get("/inline_box.js")
    assert served.headers["content-type"].startswith("text/javascript")
    assert served.headers["cache-control"] == "no-store"
    assert served.text == terminal.INLINE_BOX.read_text()
    assert "export function inlineBox" in served.text
    # one icon for the AI everywhere: the box's .ai-icon rule is app.css's, word for word
    # (the Terminal's page has no app.css, so the box carries a copy)
    css = terminal.INLINE_BOX.parents[1].joinpath("assets", "app.css").read_text()
    rule = css[css.index(".ai-icon {") : css.index("}", css.index(".ai-icon::before")) + 1]
    # a JS template string needs the glyph's backslash doubled
    assert rule.replace("\\", "\\\\") in served.text
    assert '"inline-box-icon ai-icon"' in served.text
    assert 'from "./inline_box.js"' in terminal.INLINE_BOX.with_name("inline_edit.jsx").read_text()
